#!/usr/bin/env python3
import http.server
import socketserver
import os
from pathlib import Path

PORT = 6060
HANDLER = http.server.SimpleHTTPRequestHandler

# Change to the workspace directory
os.chdir('/tmp/mcp-workspace')

# Create a custom handler to serve the HTML file
class CustomHandler(http.server.SimpleHTTPRequestHandler):
    def do_GET(self):
        if self.path == '/' or self.path == '/candidate_dashboard.html':
            self.path = '/candidate_dashboard.html'
        return super().do_GET()

with socketserver.TCPServer(("", PORT), CustomHandler) as httpd:
    print(f"Server running at http://localhost:{PORT}/")
    print(f"Serving file: /tmp/mcp-workspace/candidate_dashboard.html")
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        print("\nServer stopped.")

