const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 6060;
const HOST = 'localhost';
const FILE_PATH = '/tmp/mcp-workspace/candidate_dashboard.html';

const server = http.createServer((req, res) => {
  // Serve the HTML file for root path and direct requests
  if (req.url === '/' || req.url === '/candidate_dashboard.html') {
    fs.readFile(FILE_PATH, 'utf8', (err, data) => {
      if (err) {
        res.writeHead(404, {'Content-Type': 'text/plain'});
        res.end('File not found: ' + err.message);
        return;
      }
      res.writeHead(200, {
        'Content-Type': 'text/html; charset=utf-8',
        'Cache-Control': 'no-cache'
      });
      res.end(data);
    });
  } else {
    res.writeHead(404, {'Content-Type': 'text/plain'});
    res.end('Not found');
  }
});

server.listen(PORT, HOST, () => {
  console.log(`✓ Server running at http://${HOST}:${PORT}/`);
  console.log(`✓ Serving: ${FILE_PATH}`);
  console.log(`✓ Styles loaded exactly as designed (no modifications)`);
});

// Handle graceful shutdown
process.on('SIGINT', () => {
  console.log('\n✓ Server stopped');
  process.exit(0);
});
